#!/usr/bin/env bash\n# Test that the Terraform module contains the required resources and settings\n\nset -e\n\n# Mock rationale: we verify presence of specific resource blocks via grep\n\nif grep -q 'resource "aws_s3_bucket" "safehouse"' src/main.tf && \
   grep -q 'resource "random_pet" "bucket_name"' src/main.tf; then\n  echo "PASS: Required resources present"\nelse\n  echo "FAIL: Required resources missing"\n  exit 1\nfi\n\n# Ensure lifecycle rule expires after 30 days\nif grep -q 'days = 30' src/main.tf; then\n  echo "PASS: Lifecycle rule set to 30 days"\nelse\n  echo "FAIL: Lifecycle rule not set correctly"\n  exit 1\nfi\n\n# Ensure versioning is enabled\nif grep -q 'versioning {' src/main.tf && grep -q 'enabled = true' src/main.tf; then\n  echo "PASS: Versioning enabled"\nelse\n  echo "FAIL: Versioning not enabled"\n  exit 1\nfi\n\n# Ensure server‑side encryption is configured\nif grep -q 'sse_algorithm = "AES256"' src/main.tf; then\n  echo "PASS: Server‑side encryption configured"\nelse\n  echo "FAIL: Server‑side encryption missing"\n  exit 1\nfi\n\necho "All tests passed."\n
